import{_ as a,o as i,c as t,a2 as r}from"./chunks/framework.BjkiRu3Q.js";const l="/assets/17a4f7857494337a-20261015000315-fml9haa.JUZB_1KC.png",o="/assets/5d0dae7eb6995558-20261015000315-3iiic86.CJZXHYNp.png",f=JSON.parse('{"title":"Win10离线安装.NET Framework 3.5的方法之一使用CAB格式离线安装包","description":"","frontmatter":{"title":"Win10离线安装.NET Framework 3.5的方法之一使用CAB格式离线安装包","date":"2026-10-14T16:03:15.000Z","lastmod":"2026-11-23T06:19:38.000Z"},"headers":[],"relativePath":"guide/EntisMAXIV/EntisMaxIV帮助文档/安装卸载说明/Net Framework安装卸载说明/Win10离线安装.NET Framework 3.5的方法之一使用CAB格式离线安装包.md","filePath":"guide/EntisMAXIV/EntisMaxIV帮助文档/安装卸载说明/Net Framework安装卸载说明/Win10离线安装.NET Framework 3.5的方法之一使用CAB格式离线安装包.md"}'),n={name:"guide/EntisMAXIV/EntisMaxIV帮助文档/安装卸载说明/Net Framework安装卸载说明/Win10离线安装.NET Framework 3.5的方法之一使用CAB格式离线安装包.md"};function s(c,e,d,m,p,_){return i(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="win10离线安装-net-framework-3-5的方法之一使用cab格式离线安装包" tabindex="-1">Win10离线安装.NET Framework 3.5的方法之一使用CAB格式离线安装包 <a class="header-anchor" href="#win10离线安装-net-framework-3-5的方法之一使用cab格式离线安装包" aria-label="Permalink to &quot;Win10离线安装.NET Framework 3.5的方法之一使用CAB格式离线安装包&quot;">​</a></h1><p>‍</p><p>一般随软件的安装光盘或U盘有exe格式的.NET Framework 3.5离线安装包。但反映安装过程中会出现错误提示安装失败，所以这里再分享一下cab格式的.NET Framework 3.5离线安装包的安装方法</p><h3 id="下载链接" tabindex="-1">下载链接 <a class="header-anchor" href="#下载链接" aria-label="Permalink to &quot;下载链接&quot;">​</a></h3><ul><li>百度网盘下载:   链接: <a href="https://pan.baidu.com/s/1ODiNHQUm_PzlEIQr6JbPKg" target="_blank" rel="noreferrer">https://pan.baidu.com/s/1ODiNHQUm_PzlEIQr6JbPKg</a>    提取码: rxgt</li><li>直接下载 <a href="http://publish.softcool.cn/DotNet/NetFrameWork3.5/NetFx3.cab" target="_blank" rel="noreferrer">http://publish.softcool.cn/DotNet/NetFrameWork3.5/NetFx3.cab</a></li></ul><h3 id="安装前准备-有些准备工作并不是必须的-等安装失败后-再进行尝试也可以-毕竟不同的环境情况是不一样的" tabindex="-1">安装前准备（有些准备工作并不是必须的，等安装失败后，再进行尝试也可以，毕竟不同的环境情况是不一样的）: <a class="header-anchor" href="#安装前准备-有些准备工作并不是必须的-等安装失败后-再进行尝试也可以-毕竟不同的环境情况是不一样的" aria-label="Permalink to &quot;安装前准备（有些准备工作并不是必须的，等安装失败后，再进行尝试也可以，毕竟不同的环境情况是不一样的）:&quot;">​</a></h3><ul><li>关掉所有杀毒软件及电脑管理管家等如360安全卫士(可选)。</li><li>打开服务中的WINDOWS UPDATE自动更新(可选)</li><li>关闭win10自带防火墙(可选,遇到错误代码0x800f081f使用)</li><li>关闭.net framework 4.X高级服务,等3.5安装完成后，可以再开启,不同的Win10版本，有可能是4.6,也可能是4.7(可选,遇到错误代码0x800f0922使用)</li><li>如果有安装额外的windows语言包，先删除自己安装的windows语言包(可选)</li><li>下载NetFx3.cab的离线安装包并copy到Win10系统盘C:\\Windows文件夹里</li></ul><h3 id="安装执行" tabindex="-1">安装执行 <a class="header-anchor" href="#安装执行" aria-label="Permalink to &quot;安装执行&quot;">​</a></h3><ol><li>在windows运行中输入Cmd.exe搜索，然后在搜索出的执行文件右键点击，并选择“以管理员身份运行“，或者在Windows图标上点击右键。如图 <img src="'+l+'" alt="21185200"></li><li>在弹出的命令提示符框中粘贴命令：dism.exe /online /add-package /packagepath:C:\\WINDOWS\\netfx3.caB <img src="'+o+'" alt="9720391.png"></li><li>看到进度条并有释放空间字样，就成功了。</li></ol><h3 id="总结说明" tabindex="-1">总结说明 <a class="header-anchor" href="#总结说明" aria-label="Permalink to &quot;总结说明&quot;">​</a></h3><p>♦如果这个命令没有成功，也可以尝试使用如下命令</p><ol><li>dism /online /Enable-Feature /FeatureName:NetFx3 /Source:”%windir%” /LimitAccess</li><li>在执行时，如果失败，可以尝试去掉后缀/LimitAccess后，再尝试</li><li>如果还是失败，再尝试把”%windir%”替换成”NetFx3″,如 dism /online /Enable-Feature /FeatureName:NetFx3 /Source:”NetFx3″ /LimitAccess</li><li>如果还是错误，请把NetFx3.cab,解压到一个目录，然后把”NetFx3″替换成解压到的目录</li></ol><p>♦再次提示，能够联网的情况下，优先使用<a href="https://softcool.cn/2018/07/05/net-framework-3-5-config/" target="_blank" rel="noreferrer">Windows控制面板中的功能开启方式</a></p><p>♦请参考百度经验一<a href="https://jingyan.baidu.com/article/455a99504abf8ea1662778bd.html" target="_blank" rel="noreferrer">：使用ISO文件离线安装的方式</a></p><p>♦请参考百度经验二：<a href="https://jingyan.baidu.com/article/375c8e19c63d5f25f2a2292e.html" target="_blank" rel="noreferrer">win10 _64位Net framework3.5装不上解决之道</a></p><p>♦下面，再放一些其他用户碰到并操作的可选方案(仅供参考)</p><p>一：碰到错误代码0x800f0922和0x800f081f时</p><ol><li>在桌面上找到“计算机”，单击右键选择“管理”， 在打开的“计算机管理”窗口中依路径“服务和应用程序——服务”打开，在列表中找到“Windows Update”并单击右键选择“停止”</li><li>按住“Win+R”键打开运行对话框，输入cmd并回车，在打开的界面输入net stop WuAuServ回车（停止windows update服务）</li><li>按住“Win+R”键打开运行对话框，输入%windir%并回车，在打开的界面找到SoftwareDistribution文件夹并将其重命名为SDold</li><li>此时再打开原来的“计算机管理”窗口中依路径“服务和应用程序——服务”打开，在列表中找到“Windows Update”并单击右键选择“启动”</li><li>然后在执行方法：dism /online /Enable-Feature /FeatureName:NetFx3 /Source:”%windir%” /LimitAccess</li></ol><p>二：一直遇到87错误代码</p><ol><li>如果有安装额外的windows语言包，先删除自己安装的windows语言包</li><li>运行命令dism.exe /quiet /norestart /online /add-package /packagepath:”D:\\NetFx3.cab”</li><li>使用360安全卫士或电脑管家之类软件清理电脑垃圾及注册表</li><li>重新运行dism /online /Enable-Feature /FeatureName:NetFx3 /Source:”%windir%” /LimitAccess</li></ol>',20)])])}const u=a(n,[["render",s]]);export{f as __pageData,u as default};
